function event(ctx: <HIGH_ENTROPY_REDACTED>, sequence: number, state: ReviewProgressEvent["state"], message: string): ReviewProgressEvent {
  return <HIGH_ENTROPY_REDACTED>({
    ...ctx,
    state,
    sequence,
    message,
    ...(state === "no_output" ? { errorCode: "reviewer_no_output" } : {}),
    ...(state === "reviewer_error" ? { errorCode: "reviewer_error" } : {}),
    ...(state === "tool_error" ? { errorCode: "review_tool_error" } : {}),
  });
}

export function progressForOutcome(ctx: <HIGH_ENTROPY_REDACTED>, outcome: <HIGH_ENTROPY_REDACTED>): ReviewProgressEvent[] {
  if (outcome === "skipped") {
    return [<HIGH_ENTROPY_REDACTED>({ ...ctx, reason: "review skipped by policy" })];
  }

  const base = [
    event(ctx, 1, "launched", "reviewer process launched"),
    event(ctx, 2, "running", "reviewer process running"),
    event(ctx, 3, "heartbeat", "reviewer heartbeat observed"),
    event(ctx, 4, "activity", "reviewer activity observed"),
