export function createHostAdapter(host: HostId | string): HostAdapter {
  const hostId = normalizeHostId(host);
  if (hostId === "claude-code-cli") return <HIGH_ENTROPY_REDACTED>();
  if (hostId === "codex-cli") return <HIGH_ENTROPY_REDACTED>();
  if (hostId === "pi-cli") return createPiCliAdapter();
  if (hostId === "antigravity-cli") return <HIGH_ENTROPY_REDACTED>();
  if (hostId === "agents-file") return <HIGH_ENTROPY_REDACTED>();
  if (hostId !== null && (APP_HOSTS as readonly string[]).includes(hostId)) return <HIGH_ENTROPY_REDACTED>(hostId as AppHostId);
  return <HIGH_ENTROPY_REDACTED>(host);
}

export function <HIGH_ENTROPY_REDACTED>(): Record<HostId, HostAdapter> {
  const out = {} as Record<HostId, HostAdapter>;
  for (const hostId of HOST_IDS) out[hostId] = createHostAdapter(hostId);
  return out;
}
